#include "resultant_lib.hpp"
int main(int argc,char**argv){if(argc<3){cerr<<"usage: build_bezout generic_resultants.txt output.txt\n";return 2;}try{init();ifstream in(argv[1]);if(!in)throw runtime_error("cannot open resultant certificate");Pol l=readp(in);int count;in>>count;if(count!=2)throw runtime_error("expected two generic resultants");vector<Pol>red;for(int i=0;i<count;i++){int a,b,bound;in>>a>>b>>bound;Pol raw=readp(in);red.push_back(readp(in));}Pol target=readp(in);if(target!=Pol{1})throw runtime_error("expected unit gcd");Pol a=red[0],b=red[1],r0=a,r1=b,v0,v1{1};int step=0;while(!r1.empty()){auto qr=fastdiv(r0,r1);Pol v2=padd(v0,pscale(fastmul(qr.first,v1),4));r0=move(r1);r1=move(qr.second);v0=move(v1);v1=move(v2);if(++step%5000==0)cerr<<"extended gcd step "<<step<<" remaining degree "<<r0.size()-1<<"\n";}if(r0.size()!=1)throw runtime_error("nonunit gcd");F c=inv(r0[0]);Pol v=pscale(v0,c);Pol numerator=padd(Pol{1},pscale(fastmul(v,b),4));auto qr=fastdiv(numerator,a);if(!qr.second.empty())throw runtime_error("Bezout quotient not exact");Pol u=qr.first;if(padd(fastmul(u,a),fastmul(v,b))!=Pol{1})throw runtime_error("Bezout identity failed");ofstream out(argv[2]);if(!out)throw runtime_error("cannot write Bezout certificate");printp(out,u);printp(out,v);printp(out,Pol{1});cerr<<"PASS explicit Bezout identity: U*R55_56 + V*R55_57 = 1\n";cerr<<"degrees U="<<u.size()-1<<" V="<<v.size()-1<<"\n";return 0;}catch(exception&e){cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
